var pontoonResult=function(){var n={h:0,d:1,c:2,s:3};return{onInputNickname:function(n){n.preventDefault();n.currentTarget.value!==""&&$(".error").addClass("hidden")},onInputDealerCards:function(n){n.preventDefault();n.currentTarget.value!==""&&$("#error-dealer").hide()},reset:function(n){n.preventDefault();location.reload()},submit:function(n){var i,r,u,t,f,e;if(n.preventDefault(),$("#success").hide(),$("#fail").hide(),$("#spinner").show(),i=$("#nickname").val(),r=$("#dealer").val(),i===""){$(".error").removeClass("hidden");$("#spinner").hide();return}if(r===""){$("#error-dealer").show();$("#spinner").hide();return}for(u=[],t=1;t<=6;t++)f=$("#hand"+t).val(),u.push(f);e={name:i,dealer:this.transformDealer(r),hands:this.transformHands(u)};$.ajax({type:"POST",url:"SetPontoonResult",data:e,dataType:"html"}).done(function(n){$("#spinner").hide();n==="true"?$("#success").show():$("#fail").show()})},transformDealer:function(n){const t=[];if(n!==""){const i=n.split(",");$.each(i,(n,i)=>{t.push(this.parseCard(i))})}return t},transformHands:function(n){const t=[];return $.each(n,(n,i)=>{if(i!==""){const r=i.split(","),u=r.map(n=>this.parseCard(n));t.push({pos:n+1,cards:u})}n++}),t},parseCard:function(t){const i=t.slice(0,-1).toUpperCase(),r=t.slice(-1);return{rank:i,suit:n[r]??0}}}}();